     "materials": [
      "经济大省挑大梁，是党中央多次强调的重要要求。习近平总书记赋予湖北加快建成中部地区崛起的重要战略支点的使命责任，经济大省挑大梁是湖北推动支点成势见效的关键举措。当前，湖北肩负经济大省挑大梁重任，要运用好“既要又要还要”的“多要”之法，应对“一难两难还难”的复杂局面，协同推进稳增长、强科技、壮产业、促改革、扩开放、防风险、惠民生等工作，实现高质量发展、高品质生活、高水平安全和高效能治理的良性互动。（材料据考生回忆整理）"
     ],
