       "answer": "关于深化整治形式主义为基层减负的通知\n各处室、直属单位：为贯彻落实中央和省委整治形式主义为基层减负有关要求，现就有关事项通知如下：\n一、精简文件会议，严控发文数量和会议频次，能合并的合并、能不开的不开。\n二、规范督查检查考核，统筹计划管理，避免多头重复、过度留痕。\n三、整治“指尖上的形式主义”，清理规范工作群、政务APP，严禁强制打卡点赞。\n四、治理报表泛滥，实行数据共享归集，杜绝多头重复报送。\n五、建立长效机制，压实牵头责任，常态化开展抽查通报，对加重基层负担行为严肃问责。\nXX厅办公室 2026年X月X日"
