       "answer": "一是生态意义重大，破解磷石膏堆存造成的土壤和水体污染，直接关系长江大保护和流域安全；二是经济意义凸显，推动磷石膏资源化利用，培育循环经济新产业新增长点；三是产业意义深远，倒逼磷化工全链条技术改造和工艺升级，提升产业竞争力；四是安全意义重要，从源头降低环境安全隐患，以高水平保护支撑高质量发展。"
