        "分论要点：①活资源，保护传承活化长江文化、荆楚文化、红色文化；②深融合，文旅+科技+体育+商业，培育新业态；③强品牌，唱响“五个一”，打造世界级文旅名片；④优供给，提升服务品质与消费环境",
