       "answer": "一是加剧恶性竞争，各地竞相压低地价、减免税收，形成“内卷式”内耗，损害财政可持续性；二是埋下履约风险，违规承诺超出政策上限，易产生债务纠纷和法律风险，损害政府公信力；三是降低招商质量，重数量轻质量，招引项目与本地产业契合度低、含金量不高；四是导致落地不实，重签约轻落地、重仪式轻服务，虚增招商数据、浪费行政资源。"
